"""同一份分镜生成网页演示顺序和 Markdown 录屏稿。"""
import json
from pathlib import Path

# title, seconds, scene, narration, pointer target
rows = [
('提出上下文问题', 8, {'intro': 0}, '先看两个句子。我们会发现，同一个词的含义，需要结合周围的内容判断。', '鼠标停在标题下方的空白处。'),
('第一句话', 12, {'intro': 1}, '第一句，我吃了一个苹果。这里的苹果，指的是一种水果。', '指向第一句中的“苹果”，停住。'),
('第二句话', 13, {'intro': 2}, '第二句，苹果发布了新手机。这里的苹果，指的是一家公司。', '指向第二句中的“苹果”，停住。'),
('找到语境线索', 22, {'intro': 3}, '同样是苹果，含义却不同。我们参考了周围的内容。吃了，帮助我们理解水果；发布了新手机，帮助我们理解公司。模型也需要利用上下文，让表示更适合当前任务。', '先指“吃了”，再指“发布了新手机”，最后移回空白处。'),
('进入预测任务', 25, {'intro': 4}, '我们这次的任务，是根据已经输入的三个 token，预测接下来的第四个 token。Attention 负责其中的信息汇总。后续网络继续处理，再由词表预测层给出候选 token 的概率。', '沿任务流程从左到右移动一次，停在 Attention。'),
('认识输入矩阵', 25, {'step': 0, 'node': 'X'}, '现在进入具体计算。这里的大写 X 是输入矩阵。它有三列，每列对应一个输入位置。每列有十个数，所以矩阵的形状是十乘三。三个位置和十个特征，是两个不同的数量。', '指向表头 x₁、x₂、x₃，再指 f1 到 f10。'),
('输入数据的含义', 22, {'step': 0, 'node': 'x3'}, '我们跟着最后一个位置，也就是 x 三。这里显示的是它的十个分量。演示采用固定随机向量。实际语言模型会把 token 转换成向量，再逐层处理。接下来要计算这个位置在当前头中的上下文表示，叫作 b 三。', '指向 x₃ 名称及其数值列。'),
('引入查询与键', 25, {'step': 1}, '为了决定从哪些位置取信息，我们先比较 x 三和 x 二。把 x 三乘以 W Q，得到 query，中文叫查询。把 x 二乘以 W K，得到 key，中文叫键。后面用它们计算匹配分数。', '指向 q₃ 的公式，再指 k₂ 的公式。'),
('为何需要投影', 28, {'step': 1, 'node': 'q'}, '这两个投影引入了可学习的参数。模型可以通过训练调整，输入中的哪些特征应该被组合、放大或减弱，从而让匹配更有利于预测。查询和被查询承担不同角色，因此分别使用 W Q 和 W K。', '停在 q₃ 的公式旁，不逐个读数。'),
('投影维度', 22, {'step': 1, 'node': 'q', 'section': 'h3'}, '输入是十维，query 是五维，因此 W Q 有五行十列。矩阵的每一行与输入向量相乘，得到一个输出分量。我们这里选择五维，参与点积的 query 和 key 需要具有相同维度。', '指向当前分量标题，再指乘积表的两列。'),
('一个分量的计算', 23, {'step': 1, 'node': 'q', 'row': 1, 'section': 'h3'}, '现在选中了 q 三的第二个分量。取 W Q 的第二行，与 x 三的十个分量逐项相乘，然后把十项乘积加起来。表格展示了每一项的来源，底部就是求和结果。', '指向第 2 个分量标题，从表格首行移到末行。'),
('查看参数矩阵', 20, {'step': 1, 'node': 'q', 'row': 1, 'parameters': True}, '这里是完整的 W Q 参数矩阵，高亮的是刚才使用的第二行。同一个头里的所有输入位置，共享这套 W Q 参数；W K 和 W V 也各自被所有位置共享。', '沿高亮的第二行移动一次。'),
('得到 key', 17, {'step': 1, 'node': 'k2'}, '对 x 二做类似的投影，得到五维的 k 二。现在，q 三和 k 二都准备好了。下一步把它们的匹配程度转换成一个分数。', '指向 k₂ 的五个数。'),
('逐项点积', 26, {'step': 2, 'node': 'pair'}, '点积的做法，是对应分量相乘，再把乘积相加。两个向量都是五维，所以这里有五项乘积。最后得到的分数大约是零点一三九一，它对应第三个位置查询第二个位置时的匹配。', '指向 q₃、k₂ 两列，再指底部求和。'),
('分数怎样影响权重', 18, {'step': 2}, '匹配分数由输入和投影参数共同决定，可以为正，也可以为负。在其他分数固定时，这个分数越大，后续分配给对应位置的注意力权重就越大。', '停在匹配分数节点旁。'),
('比较所有位置', 24, {'step': 3, 'node': 'all'}, '接下来保持 q 三不变，分别与 k 一、k 二、k 三比较，得到三个分数。这样第三个位置可以综合判断，各个位置应该贡献多少。它也会与自己比较，因为自身的信息同样可以参与汇总。', '依次指向 k1、k2、k3 三行分数。'),
('因果可见范围', 28, {'step': 3, 'node': 'X', 'section': 'h3'}, '自回归模型要求一个位置只使用当前位置和之前的信息。位置一只能看自己，位置二可以看一和二，位置三可以看一、二、三。这叫因果注意力。我们正在计算位置三，所以三个输入都可以参与。', '逐行指向可见范围表，最后停在位置 3。'),
('未来位置怎样屏蔽', 18, {'step': 3, 'node': 'X', 'section': 'h3'}, '计算时，未来位置的分数会在 softmax 前设成负无穷。取指数后对应零，最终权重也为零。这样即使训练时多个位置同时计算，每个位置也只能使用允许的信息。', '指向表中的“屏蔽”。'),
('根号五的来源', 23, {'step': 4}, '接下来先缩放，再归一化。这里除以根号五，是因为当前头的 query 和 key 都是五维。一般写成除以根号 d k。d k 表示每个头的 query 和 key 维度。', '指向解释中的 dₖ = 5 和 √dₖ = √5。'),
('为什么缩放', 25, {'step': 4}, '点积会累加多个乘积，维度增大时，分数的波动通常也会增大。如果分数差距过大，softmax 容易过早把权重集中到某个位置，使训练进入梯度较小的区域。缩放有助于控制分数尺度。', '鼠标停在解释旁的空白处。'),
('缩放后的数值', 18, {'step': 4, 'node': 'soft'}, '这是三个原始点积分数，以及除以根号五后的结果。缩放后的数大约是负零点一二四二、零点零六二二、零点零二九一。接下来对这三个数一起做 softmax。', '依次指向“÷ √5”一列。'),
('softmax 分子分母', 26, {'step': 4, 'node': 'soft', 'section': 'h3'}, 'softmax 先对每个分数取指数，再除以所有指数值的总和。为了稳定数值，这里先减去了本组最大值。分子分母中的共同因子可以约掉，所以归一化结果相同。', '指向三个指数分子，再指分母。'),
('读出注意力权重', 23, {'step': 4, 'node': 'soft', 'section': 'last-table'}, '得到的三个权重大约是零点二九六七、零点三五七五、零点三四五八。它们都是正数，而且总和为一。这些权重决定生成 b 三时，三个位置的 value 分别贡献多少。', '依次指三个权重，再指“权重之和”。'),
('引入 Value', 22, {'step': 5, 'node': 'v'}, '比例已经有了，具体汇总什么内容呢？我们用 W V 把每个输入转换成 value，中文叫值。Q 和 K 用来计算匹配与权重，V 提供最终要汇总的内容。', '指向 V 的公式及 v₁、v₂、v₃ 三列。'),
('W V 与 V', 22, {'step': 5, 'node': 'v', 'section': 'h3'}, 'W V 是可学习的参数矩阵，V 是它处理当前输入后得到的结果。这个投影让模型学习，应该向其他位置提供哪些信息。我们这里每个 value 都是五维。', '指向 W_V 的行与输入列，停在乘积表。'),
('加权求和', 23, {'step': 5, 'node': 'out'}, '现在用三个注意力权重，分别乘上三个 value 向量，再把结果相加，得到 b 三。每个权重都会乘到对应 value 的所有分量上，然后逐个分量相加。', '指向 b₃ 顶部公式，再指输出的五行。'),
('展开一个输出分量', 27, {'step': 5, 'node': 'out', 'row': 0, 'section': 'h3'}, '看第一个分量。取三个 value 的第一个数，分别乘上零点二九六七、零点三五七五和零点三四五八，再加起来。结果大约是负零点五四一九。其他四个分量也用同样的方法计算。', '逐行指向三项乘积，最后指求和结果。'),
('b 三走向哪里', 23, {'step': 5, 'node': 'later'}, 'b 三是当前一个注意力头在第三个位置的输出。完整模型会合并多个头的信息，再经过输出投影、残差连接、归一化、前馈网络和更多层的处理，形成最后位置的最终表示。', '指向后续 Transformer 计算说明。'),
('预测第四个 token', 25, {'step': 5, 'node': 'prediction'}, '最后，词表预测层把这个表示转换成每个候选 token 的分数。再对整个词表做 softmax，得到下一个 token 的概率，然后选择或采样。本页展示到了一个注意力头的真实计算，这里展示后续模型流程。', '指向词表预测说明。'),
('区分两次 softmax', 22, {'step': 5, 'node': 'prediction'}, 'Attention 内部的 softmax，在输入位置之间分配权重。输出端的 softmax，在词表中的候选 token 之间分配概率。两者使用相同的归一化方法，处理的对象不同。', '停在“对整个词表做 softmax”一句附近。'),
('回顾整条路径', 28, {'step': 5, 'overview': True}, '回到全图。为了预测下一个 token，最后位置先用 query 与各个可见 key 匹配，计算注意力权重，再按权重汇总 value，形成上下文表示。后续网络继续处理，最终产生下一个 token 的概率。', '依次指向 Q/K、softmax、V、b₃、预测出口。'),
]
root = Path(__file__).resolve().parents[1]
scenes = []
time = 0
lines = ['# Attention 录屏分镜脚本', '', '本稿与网页“按稿演示”模式使用同一份分镜数据。共 31 个镜头，时间为目标时长，包含每次切换后的 3 秒静默操作空档。实际语速可在试读后调整，网页按点击推进。', '', '## 录制准备', '', '1. 打开本地网页，建议桌面浏览器窗口至少 1280 × 900，浏览器缩放 100%。', '2. 点击顶部“按稿演示”。网页进入开场第一个镜头。', '3. 每一行开始时点击底部“下一镜”，等待画布稳定。首行已经就位。点击期间保持安静。', '4. 按“指向”列移动鼠标，然后朗读配音列。没有额外点击要求时，停住鼠标。', '5. 下一镜会自动进入对应步骤、展开节点、选中分量和定位表格。补录时使用镜头下拉框直接选择。', '6. 数学读法统一为“x 三”“q 三”“k 二”“W Q”“d k”“b 三”。表中的文字是逐字稿，标点表示自然停顿。', '', '## 逐镜头讲解', '', '| 镜头与目标时间 | 操作与指向 | 逐字配音 |', '|---|---|---|']
def clock(t): return f'{t//60:02d}:{t%60:02d}'
for index, (title, seconds, scene, speech, pointer) in enumerate(rows):
    start = time
    speech_start = time + 3
    time += seconds + 3
    scenes.append(dict(title=title, start=start, speechStart=speech_start, end=time, scene=scene, speech=speech, pointer=pointer))
    action = '点击“按稿演示”' if index == 0 else '点击“下一镜”'
    lines.append(f'| {index+1}. {title}<br>{clock(start)}–{clock(time)} | **{clock(start)}–{clock(speech_start)}** {action}，静默等待画面稳定。<br>**{clock(speech_start)} 开始** {pointer} | {speech} |')
lines += ['', '## 配音与画面核对', '', '- 出现的“苹果”句子是上下文示意，演示中的矩阵是固定随机输入。', '- 开场是对上下文作用的一般说明。因果预测的可见范围在第 17、18 镜明确讲解。', '- 当前主角始终是 x₃，输出是当前注意力头的 b₃。', '- 画布只展示当前头的实际数值，后续网络和词表预测是流程说明。', '- “按稿演示”可以随时退出，退出后可自由探索画布。', '', f'目标总时长为 {clock(time)}。']
(root/'dist/recording.json').write_text(json.dumps(scenes,ensure_ascii=False,indent=2))
(root/'录屏讲解稿.md').write_text('\n'.join(lines)+'\n')
print(f'{len(scenes)} scenes, {clock(time)} total')
